CREATE TABLE customers (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FullName" character varying(200) NOT NULL,
    "Company" character varying(200) NOT NULL,
    "Phone" character varying(50) NOT NULL,
    "Email" character varying(200),
    "Notes" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_customers" PRIMARY KEY ("Id")
);


CREATE TABLE devices (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "InstallationId" character varying(64) NOT NULL,
    "Fingerprint" character varying(128) NOT NULL,
    "MachineName" character varying(200) NOT NULL,
    "AppVersion" character varying(32) NOT NULL,
    "FirstSeenAt" timestamp with time zone NOT NULL,
    "LastSeenAt" timestamp with time zone NOT NULL,
    "LastIp" character varying(64),
    CONSTRAINT "PK_devices" PRIMARY KEY ("Id")
);


CREATE TABLE license_events (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "At" timestamp with time zone NOT NULL,
    "LicenseId" integer,
    "DeviceId" integer,
    "Action" character varying(50) NOT NULL,
    "Details" text,
    "Ip" character varying(64),
    CONSTRAINT "PK_license_events" PRIMARY KEY ("Id")
);


CREATE TABLE licenses (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Key" character varying(40) NOT NULL,
    "CustomerId" integer NOT NULL,
    "Type" character varying(20) NOT NULL,
    "Status" character varying(20) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "ExpiresAt" timestamp with time zone,
    "MaxDevices" integer NOT NULL,
    "BlockReason" text,
    "Notes" text,
    CONSTRAINT "PK_licenses" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_licenses_customers_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES customers ("Id") ON DELETE RESTRICT
);


CREATE TABLE activations (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "LicenseId" integer NOT NULL,
    "DeviceId" integer NOT NULL,
    "ActivatedAt" timestamp with time zone NOT NULL,
    "LastCheckAt" timestamp with time zone NOT NULL,
    "IsActive" boolean NOT NULL,
    "DeactivatedAt" timestamp with time zone,
    CONSTRAINT "PK_activations" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_activations_devices_DeviceId" FOREIGN KEY ("DeviceId") REFERENCES devices ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_activations_licenses_LicenseId" FOREIGN KEY ("LicenseId") REFERENCES licenses ("Id") ON DELETE CASCADE
);


CREATE INDEX "IX_activations_DeviceId" ON activations ("DeviceId");


CREATE INDEX "IX_activations_LicenseId_IsActive" ON activations ("LicenseId", "IsActive");


CREATE INDEX "IX_devices_Fingerprint" ON devices ("Fingerprint");


CREATE UNIQUE INDEX "IX_devices_InstallationId" ON devices ("InstallationId");


CREATE INDEX "IX_license_events_At" ON license_events ("At");


CREATE INDEX "IX_licenses_CustomerId" ON licenses ("CustomerId");


CREATE UNIQUE INDEX "IX_licenses_Key" ON licenses ("Key");


